  return <div className="page manager-v2"><div className="page-heading"><div><span className="eyebrow">MANAGER WORKSPACE</span><h2>Tasks</h2><p className="muted">Create, search, assign and open work items by project.</p></div></div><div className="task-command"><label>Project<select value={projectId} onChange={e=>setProjectId(e.target.value)}><option value="">Select project</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>Search / filter tasks<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search task title"/></label><button className="button primary" onClick={()=>setShowCreate(true)}>Create issue / task</button></div>{showCreate&&<div className="modal-backdrop"><div className="issue-modal"><CreateIssue form={form} setForm={setForm} projects={projects} users={users} close={()=>setShowCreate(false)} submit={create}/></div></div>}<div className="kanban">{STATUS.map(([status,label])=><section className="kanban-col" key={status}><div className="kanban-head"><strong>{label}</strong><span>{shown.filter(t=>t.status===status).length}</span></div>{shown.filter(t=>t.status===status).map(task=><IssueCard key={task.id} issue={task} projects={projects} open={open}>{status==='testing'&&<div className="tester-controls"><label>Assign tester<select value={task.testing_assigned_to?.[0]||''} onChange={e=>assignTester(task,e.target.value)}><option value="">Select employee</option>{users.filter(u=>u.role==='employee').map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label><button type="button" className="button primary" onClick={e=>{e.stopPropagation();assignTester(task,task.testing_assigned_to?.[0]||'')}}>Send</button></div>}</IssueCard>)}{!shown.some(t=>t.status===status)&&<Empty>No tasks here.</Empty>}</section>)}</div>{selected&&<IssueDialog initialIssue={selected} projects={projects} users={users} close={()=>setSelected(null)} changed={updated=>updated?setTasks(rows=>rows.map(x=>x.id===updated.id?updated:x)):load()}/>} {error&&<div className="alert error">{error.message}</div>}</div>
